package main

import (
	"strconv"
	"strings"
	"time"

	"github.com/mellifera/mellifera/internal/orchestrator"
	"github.com/mellifera/mellifera/internal/store"
)

// Completion-aware watched semantics (tv-playback-unblock design D5): the
// frontier's watch signal. An item counts as watched exactly when its stored
// position has reached the main content's end — judged as 90% of a known
// duration OR the start of a classified credits/ending section — and never as
// bare any-positive-position. The facts are the item document's stored ffprobe
// blob ({"format": {"duration": ...}, "chapters": [...]}), read where the
// sweep's serial loop already projects every episode — no extra store reads.
// The credits classifier mirrors the SPA's web/src/lib/skipSections.ts rule
// exactly; the miss direction is conservative (an unknown title or unparseable
// boundary only downgrades to the 90% rule, and a false positive needs an
// exact lexicon title), so a serial with neither usable fact stays unwatched —
// its tail stays fronted and proactively built.

// watchedDurationFloor is the fraction of a known duration that counts as a
// completed watch: 100% is never required (design D5).
const watchedDurationFloor = 0.9

// creditsTitles is the credits lexicon — the SPA classifier's exact
// trimmed-lowercase titles (Cyrillic muxer titles included). Substring
// matching is deliberately NOT used: "ed" inside "Wedding" must never
// classify a credits section.
var creditsTitles = map[string]struct{}{
	"credits": {},
	"титры":   {},
	"ending":  {},
	"outro":   {},
	"ed":      {},
}

// episodeWatched applies the completion-aware predicate to one item's stored
// facts and playback position: watched = (duration known AND position >= 90%
// of duration) OR (a classified credits section exists AND position >= its
// start). Missing duration AND missing credits is not watched — conservative:
// the tail stays fronted (spec "Completion-aware watched semantics").
func episodeWatched(doc map[string]any, position float64) bool {
	if dur, ok := thumbProbeDuration(doc["ffprobe"]); ok && position >= watchedDurationFloor*dur {
		return true
	}
	if start, ok := creditsStartSeconds(doc["ffprobe"]); ok && position >= start {
		return true
	}
	return false
}

// projectEpisodes projects one serial's item rows into the orchestrator's
// Episode inputs (episodeFromDoc) and folds the completion-aware predicate
// into the watched set — the sweep serial loop's seam: the episode documents
// are already in hand, so the predicate costs no extra store reads. watched is
// mutated in place (the FrontierIn.Watched map the orchestrator consumes as
// the plain itemID → bool input; its own logic and shapes are unchanged).
func projectEpisodes(items []store.Item, cool map[string]time.Time, optInCodecs bool, positions map[string]float64, watched map[string]bool) []orchestrator.Episode {
	eps := make([]orchestrator.Episode, 0, len(items))
	for _, it := range items {
		doc := decodeItemDoc(it.Document)
		eps = append(eps, episodeFromDoc(it.ID, doc, cool, optInCodecs))
		if episodeWatched(doc, positions[it.ID]) {
			watched[it.ID] = true
		}
	}
	return eps
}

// creditsStartSeconds returns the earliest start among the stored ffprobe
// chapters that classify as credits/ending under the SPA classifier's exact
// rule: a container chapter with start and end present, end > start, and a
// trimmed-lowercase title in the credits lexicon. ok is false when no chapter
// classifies — the predicate then falls back to the duration floor alone.
func creditsStartSeconds(raw any) (float64, bool) {
	probe, ok := raw.(map[string]any)
	if !ok {
		return 0, false
	}
	chapters, ok := probe["chapters"].([]any)
	if !ok {
		return 0, false
	}
	best, found := 0.0, false
	for _, c := range chapters {
		ch, ok := c.(map[string]any)
		if !ok {
			continue
		}
		start, ok := chapterSeconds(ch, "start")
		if !ok {
			continue
		}
		end, ok := chapterSeconds(ch, "end")
		if !ok || end <= start {
			continue // a degenerate or end-less range is never a skip range
		}
		title := chapterTitle(ch)
		if _, ok := creditsTitles[strings.ToLower(strings.TrimSpace(title))]; !ok {
			continue // unknown title classifies to nothing — never a substring
		}
		if !found || start < best {
			best, found = start, true // earliest credits start is the threshold
		}
	}
	return best, found
}

// chapterSeconds resolves a chapter boundary in seconds — the mirror of the
// stream projection's boundary rule: ffprobe reports both *_time ("12.345678",
// the scaled string, preferred) and the raw integer in the chapter's
// time_base, which the raw form is converted through. ok is false when
// neither is usable.
func chapterSeconds(ch map[string]any, field string) (float64, bool) {
	if v, ok := ch[field+"_time"].(string); ok {
		if f, err := strconv.ParseFloat(strings.TrimSpace(v), 64); err == nil {
			return f, true
		}
	}
	raw, ok := ch[field].(float64)
	if !ok {
		return 0, false
	}
	if num, den, ok := chapterTimeBase(ch); ok {
		return raw * num / den, true
	}
	return 0, false
}

// chapterTimeBase parses a chapter's "1/1000"-shaped time_base. ok is false
// when absent or malformed (the raw-integer fallback then gives up).
func chapterTimeBase(ch map[string]any) (num, den float64, ok bool) {
	tb, _ := ch["time_base"].(string)
	numS, denS, found := strings.Cut(tb, "/")
	n, err1 := strconv.ParseFloat(strings.TrimSpace(numS), 64)
	d, err2 := strconv.ParseFloat(strings.TrimSpace(denS), 64)
	if !found || err1 != nil || err2 != nil || n == 0 || d == 0 {
		return 0, 0, false
	}
	return n, d, true
}

// chapterTitle reads a chapter's title, tolerating absent facts — the mirror
// of the stream projection's read: real `ffprobe -show_chapters` output nests
// the title under tags.title; the top-level "title" is the fallback shape.
func chapterTitle(ch map[string]any) string {
	if tags, ok := ch["tags"].(map[string]any); ok {
		if t, ok := tags["title"].(string); ok {
			return t
		}
	}
	t, _ := ch["title"].(string)
	return t
}
